const fontRules = [
  ...extractFonts(bundleCss, bundleCssSrcDir, { fontsOut, roots: fontRoots }),
  ...(explicitCss ? extractFonts(explicitCss, dirname(explicitCss), { fontsOut, roots: PKG_DIR }) : []),
