      .join('');
    const kids = typeof a.children === 'string' ? fsan(a.children).slice(0, 80) : '';
    return `// ${fsan(s.name)}\n<${c.name}${propStr}${kids ? `>${kids}</${c.name}>` : ' />'}`;
