export function emitPerComponent({ src, components, OUT, GLOBAL, PKG, VERSION, OVERRIDES, REPLACES, PROVIDER, hasDecorators, exported, builtPreviews, propsBodyFor, compoundsFor, smartDefaultProps, previewArgs }) {
